  function activeMedia(){return (snap.media||[]).filter(m=>Number(m.active)===1)}
  function mediaByKey(key){return (snap.media||[]).find(m=>String(m.media_key)===String(key))||null}
  function itemMediaKey(item){return String(item.image_path||'').replace(/^media:/,'')}
