  function focalValue(v){const n=Number(v);return Number.isFinite(n)?Math.max(0,Math.min(1,n)):.5}
  function applyFocal(img,m){if(!img||!m)return;img.style.objectPosition=`${(focalValue(m.focal_x)*100).toFixed(2)}% ${(focalValue(m.focal_y)*100).toFixed(2)}%`}
  function normalize(v){return String(v||'').toLocaleLowerCase('fa-IR').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/\s+/g,' ').trim()}
  function fileSize(n){const bytes=Number(n||0);return bytes>=1024*1024?`${(bytes/1024/1024).toLocaleString('fa-IR',{maximumFractionDigits:1})} مگابایت`:`${Math.max(1,Math.round(bytes/1024)).toLocaleString('fa-IR')} کیلوبایت`}
  function mediaFilterLabel(key){return ({active:'همه تصاویر فعال',used:'در حال استفاده',unused:'بدون استفاده',archived:'آرشیو'})[key]||'کتابخانه رسانه'}
  function mediaOrientationOf(m){const w=Number(m.width_px||0),h=Number(m.height_px||0);if(w<=0||h<=0)return 'unknown';const ratio=w/h;if(ratio>=.9&&ratio<=1.1)return 'square';return ratio>1.1?'landscape':'portrait'}
  function mediaCreatedValue(m){const raw=String(m.created_at||'').trim();if(!raw)return 0;const normalized=raw.includes('T')?raw:raw.replace(' ','T')+'Z';const v=Date.parse(normalized);return Number.isFinite(v)?v:0}
  function renderMediaSummary(){const all=snap.media||[],active=all.filter(m=>Number(m.active)===1),used=active.filter(m=>Number(m.reference_count||0)>0),unused=active.filter(m=>Number(m.reference_count||0)===0),archived=all.filter(m=>Number(m.active)!==1);[['active',active.length],['used',used.length],['unused',unused.length],['archived',archived.length]].forEach(([key,count])=>{const metric=$(`[data-media-metric="${key}"]`);if(metric)metric.textContent=L.integer(count)});$$('[data-media-quick-filter]').forEach(b=>{const on=b.dataset.mediaQuickFilter===mediaFilter;b.classList.toggle('is-active',on);b.setAttribute('aria-pressed',on?'true':'false')})}
  function renderIdentity(){const draft=snap.draft_identity||{},published=snap.published_identity||{},active=Boolean(draft.active),media=active?mediaByKey(draft.media_key):null,img=$('[data-identity-preview-img]'),fallback=$('[data-identity-fallback]'),name=$('[data-identity-name]'),meta=$('[data-identity-meta]'),state=$('[data-identity-status]'),pub=$('[data-identity-publish-state]'),reset=$('[data-identity-reset]');if(img){img.hidden=!media;if(media){img.src=imageUrl(media);img.alt=media.alt_text||'نشان مجموعه'}else img.removeAttribute('src')}if(fallback)fallback.hidden=Boolean(media);if(name)name.textContent=media?(media.original_name||'نشان انتخاب‌شده'):'نشان پیش‌فرض';if(meta)meta.textContent=media?`${L.integer(media.width_px||0)}×${L.integer(media.height_px||0)} · نسخه ${String(draft.version||'').slice(0,12)}…`:'از نشان داخلی سکنا استفاده می‌شود.';const same=Boolean(draft.active)===Boolean(published.active)&&String(draft.media_key||'')===String(published.media_key||'')&&String(draft.version||'fallback')===String(published.version||'fallback');if(state){state.textContent=same?'همگام با نسخه عمومی':'تغییر منتشرنشده';state.className=`sc-badge ${same?'sc-badge--success':'sc-badge--warning'}`}if(pub)pub.textContent=same?'هویت تصویری منتشرشده با پیش‌نویس یکی است.':'این تغییر فعلاً فقط در Local دیده می‌شود؛ برای وب عمومی «انتشار پیش‌نویس» را بزن.';if(reset)reset.hidden=!active}
  function openIdentityPicker(){pickerMode='identity';pickerItemId=0;pickerSelectedKey=String(snap.draft_identity?.media_key||'');pickerQuery='';const search=$('[data-media-picker-search]');if(search)search.value='';renderPicker();{const d=$('[data-media-picker-dialog]');if(!window.SoknaUI?.showDialog?.(d,{initialFocus:'[data-media-picker-search]'}))d?.showModal?.()}}
  const IDENTITY_SIZES={'logo-256':256,'icon-16':16,'icon-32':32,'icon-48':48,'icon-180':180,'icon-192':192,'icon-512':512};
  function loadIdentityImage(media){return new Promise((resolve,reject)=>{const image=new Image();image.decoding='async';image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('خواندن تصویر برای ساخت نشان انجام نشد.'));image.src=imageUrl(media)})}
  async function buildIdentityVariants(media){if(Math.min(Number(media.width_px||0),Number(media.height_px||0))<192)throw new Error('برای نشان مجموعه، ضلع کوتاه تصویر باید حداقل ۱۹۲ پیکسل باشد.');const image=await loadIdentityImage(media),sw=image.naturalWidth||Number(media.width_px||0),sh=image.naturalHeight||Number(media.height_px||0),side=Math.min(sw,sh),sx=Math.max(0,(sw-side)/2),sy=Math.max(0,(sh-side)/2),out={};for(const [key,size] of Object.entries(IDENTITY_SIZES)){const canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d',{alpha:true});if(!ctx)throw new Error('مرورگر امکان ساخت خروجی نشان را ندارد.');ctx.clearRect(0,0,size,size);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(image,sx,sy,side,side,0,0,size,size);out[key]=canvas.toDataURL('image/png')}return out}
  function visibleMedia(){const q=normalize(mediaQuery);const rows=(snap.media||[]).filter(m=>{const active=Number(m.active)===1,used=Number(m.reference_count||0)>0;if(mediaFilter==='active'&&!active)return false;if(mediaFilter==='used'&&(!active||!used))return false;if(mediaFilter==='unused'&&(!active||used))return false;if(mediaFilter==='archived'&&active)return false;if(mediaType!=='all'&&String(m.mime||'')!==mediaType)return false;if(mediaOrientation!=='all'&&mediaOrientationOf(m)!==mediaOrientation)return false;if(q&&!normalize(`${m.original_name} ${m.alt_text} ${m.media_key} ${m.mime}`).includes(q))return false;return true});rows.sort((a,b)=>{if(mediaSort==='oldest')return mediaCreatedValue(a)-mediaCreatedValue(b)||Number(a.id)-Number(b.id);if(mediaSort==='name')return String(a.original_name||'').localeCompare(String(b.original_name||''),'fa')||Number(b.id)-Number(a.id);if(mediaSort==='usage')return Number(b.reference_count||0)-Number(a.reference_count||0)||mediaCreatedValue(b)-mediaCreatedValue(a);if(mediaSort==='size_desc')return Number(b.byte_size||0)-Number(a.byte_size||0)||mediaCreatedValue(b)-mediaCreatedValue(a);if(mediaSort==='size_asc')return Number(a.byte_size||0)-Number(b.byte_size||0)||mediaCreatedValue(b)-mediaCreatedValue(a);return mediaCreatedValue(b)-mediaCreatedValue(a)||Number(b.id)-Number(a.id)});return rows}
  function mediaCard(m){const archived=Number(m.active)!==1,used=Number(m.reference_count||0)>0,card=el('article','sc-media-card'+(archived?' is-archived':'')+(mediaView==='list'?' is-list':''));card.dataset.mediaKey=m.media_key;const open=el('button','sc-media-card__open');open.type='button';open.setAttribute('aria-label',`دیدن جزئیات ${m.original_name||'تصویر'}`);const thumb=el('div','sc-media-card__thumb');if(!archived){const img=document.createElement('img');img.src=imageUrl(m);img.alt=m.alt_text||m.original_name||'';img.loading='lazy';applyFocal(img,m);thumb.append(img)}else thumb.append(el('span','sc-media-card__archived','آرشیو'));const state=el('span',`sc-media-card__state sc-badge ${used?'sc-badge--success':archived?'sc-badge--neutral':''}`,archived?'آرشیو':used?`${L.integer(m.reference_count)} استفاده`:'بدون استفاده');thumb.append(state);
    const body=el('div','sc-media-card__body');body.append(el('strong','',m.original_name||'تصویر'));const meta=el('small','',`${m.width_px?L.integer(m.width_px):'?'}×${m.height_px?L.integer(m.height_px):'?'} · ${String(m.extension||'').toUpperCase()||'IMAGE'} · ${fileSize(m.byte_size)}`);body.append(meta);const secondary=el('small','sc-media-card__secondary',m.alt_text?m.alt_text:'متن جایگزین ثبت نشده');body.append(secondary);open.append(thumb,body);open.addEventListener('click',()=>openMediaDetail(m));card.append(open);return card}
  function renderMediaControls(total){const count=$('[data-media-result-count]'),label=$('[data-media-active-filter-label]'),reset=$('[data-media-reset-filters]'),grid=$('[data-media-grid]');if(count)count.textContent=`${L.integer(total)} تصویر`;if(label)label.textContent=mediaFilterLabel(mediaFilter);const hasExtra=mediaQuery.trim()!==''||mediaType!=='all'||mediaOrientation!=='all'||mediaSort!=='newest';if(reset)reset.hidden=!hasExtra;if(grid)grid.dataset.view=mediaView;$$('[data-media-view]').forEach(b=>{const on=b.dataset.mediaView===mediaView;b.classList.toggle('is-active',on);b.setAttribute('aria-pressed',on?'true':'false')});renderMediaSummary()}
  function renderMediaPager(total){const pager=$('[data-media-pager]');if(!pager)return;const pages=Math.max(1,Math.ceil(total/MEDIA_PAGE_SIZE));mediaPage=Math.min(Math.max(1,mediaPage),pages);pager.hidden=total<=MEDIA_PAGE_SIZE;const label=$('[data-media-page-label]',pager);if(label)label.textContent=`صفحه ${L.integer(mediaPage)} از ${L.integer(pages)} · ${L.integer(total)} تصویر`;const prev=$('[data-media-page-prev]',pager),next=$('[data-media-page-next]',pager);if(prev)prev.disabled=mediaPage<=1;if(next)next.disabled=mediaPage>=pages}
