  function uploadEntryRequest(entry){return new Promise(resolve=>{const fd=new FormData();fd.append('csrf_token',csrf);fd.append('media',entry.file,entry.file.name);fd.append('alt_text',entry.altText||'');const xhr=new XMLHttpRequest();entry.xhr=xhr;entry.state='uploading';entry.progress=5;renderUploadQueue();xhr.open('POST',uploadUrl,true);xhr.withCredentials=true;xhr.timeout=60000;xhr.setRequestHeader('Accept','application/json');xhr.upload.onprogress=e=>{if(e.lengthComputable&&entry.state==='uploading'){entry.progress=Math.max(5,Math.min(94,Math.round(e.loaded/e.total*90)));renderUploadQueue()}};xhr.upload.onload=()=>{if(entry.state==='uploading'){entry.state='processing';entry.progress=95;renderUploadQueue()}};xhr.onload=()=>{let data={};try{data=JSON.parse(xhr.responseText||'{}')}catch(_){data={success:false,message:'پاسخ بارگذاری قابل خواندن نیست.'}}if(xhr.status>=200&&xhr.status<300&&data.success!==false){entry.state='ready';entry.progress=100;entry.mediaKey=String(data.result?.media_key||'');entry.deduplicated=Boolean(data.result?.deduplicated);entry.error='';if(entry.mediaKey)lastUploadedMediaKey=entry.mediaKey}else{entry.state='failed';entry.error=data.message||`بارگذاری با خطای ${xhr.status||'شبکه'} متوقف شد.`}entry.xhr=null;renderUploadQueue();resolve()};xhr.onerror=()=>{entry.state='failed';entry.error='ارتباط هنگام بارگذاری قطع شد؛ فقط همین فایل را دوباره تلاش کن.';entry.xhr=null;renderUploadQueue();resolve()};xhr.ontimeout=()=>{entry.state='failed';entry.error='زمان بارگذاری این فایل تمام شد؛ دوباره تلاش کن.';entry.xhr=null;renderUploadQueue();resolve()};xhr.onabort=()=>{entry.state='cancelled';entry.error='';entry.xhr=null;renderUploadQueue();resolve()};xhr.send(fd)})}
  async function processUploadEntry(entry){entry.cancelRequested=false;entry.state='validating';entry.error='';entry.progress=0;renderUploadQueue();try{await validateImageFile(entry)}catch(err){if(entry.cancelRequested||err.message==='cancelled'){entry.state='cancelled';entry.error=''}else{entry.state='failed';entry.error=err.message||'اعتبارسنجی فایل انجام نشد.'}renderUploadQueue();return}if(entry.cancelRequested){entry.state='cancelled';renderUploadQueue();return}await uploadEntryRequest(entry)}
  async function pumpUploadQueue(){if(uploadPumping)return;uploadPumping=true;try{while(true){const active=uploadQueue.filter(e=>['validating','uploading','processing'].includes(e.state)).length;if(active>=UPLOAD_CONCURRENCY){await new Promise(r=>setTimeout(r,30));continue}const next=uploadQueue.find(e=>e.state==='queued');if(!next){if(active===0)break;await new Promise(r=>setTimeout(r,30));continue}processUploadEntry(next).finally(()=>{});await new Promise(r=>setTimeout(r,0))}}finally{uploadPumping=false;renderUploadQueue();await refresh().catch(()=>{});const ready=uploadQueue.filter(e=>e.state==='ready').length,failed=uploadQueue.filter(e=>e.state==='failed').length;if(ready)toast(`${L.integer(ready)} تصویر در Local آماده است.${failed?' بعضی فایل‌ها نیاز به تلاش دوباره دارند.':''}`,failed?'warning':'success');if(pickerReturnToUpload&&(pickerMode==='identity'||pickerItemId)&&lastUploadedMediaKey){pickerSelectedKey=lastUploadedMediaKey;if($('[data-media-picker-dialog]')?.open)renderPicker()}}}
