  function cancelUploadEntry(id){const entry=uploadQueue.find(e=>e.id===id);if(!entry)return;entry.cancelRequested=true;if(entry.xhr)entry.xhr.abort();else if(['queued','validating'].includes(entry.state)){entry.state='cancelled';entry.error='';renderUploadQueue()}}
