  function retryAllUploads(){uploadQueue.filter(e=>e.state==='failed').forEach(e=>{e.state='queued';e.progress=0;e.error='';e.cancelRequested=false});renderUploadQueue();void pumpUploadQueue()}
  function clearFinishedUploads(){if(uploadQueueBusy())return;uploadQueue=uploadQueue.filter(e=>!['ready','cancelled'].includes(e.state));if(!uploadQueue.length)lastUploadedMediaKey='';renderUploadQueue()}

